// argparse actions — mirrors CPython 3.12 `argparse.Action`, `_StoreAction`
// and `_HelpAction`. This layer only *stores* an argument's configuration and
// applies values to the namespace; all layout/wrapping lives in formatter.mjs.

import { PyValueError } from '../py/errors.mjs';

// CPython: argparse.SUPPRESS. A sentinel default meaning "do not put this dest
// into the namespace at all" (see _parse_known_args' default-seeding loop).
export const SUPPRESS = '==SUPPRESS==';

// CPython: argparse.OPTIONAL ('?'), only needed for _StoreAction's const check.
const OPTIONAL = '?';

/**
 * Normalise constructor arguments.
 *
 * CPython builds actions with keyword arguments whose names are snake_case
 * (`option_strings`, `const`, `default`, ...). Callers here may use either the
 * camelCase field names or the Python keyword names, and may also pass the
 * `(optionStrings, dest, options)` positional prefix that CPython's signature
 * begins with. All shapes collapse to one options object.
 */
function normalizeOptions(args) {
  const [first, second, third] = args;
  if (typeof first === 'string' || Array.isArray(first)) {
    const rest = third ?? {};
    return { ...rest, optionStrings: first, dest: second ?? rest.dest };
  }
  return first ?? {};
}

export class Action {
  constructor(...args) {
    const opts = normalizeOptions(args);
    const optionStrings = opts.optionStrings ?? opts.option_strings ?? [];

    // '--a' alone is accepted as shorthand for ['--a'].
    this.optionStrings = typeof optionStrings === 'string' ? [optionStrings] : [...optionStrings];
    this.dest = opts.dest ?? null;
    this.nargs = opts.nargs ?? null; // Python None => "exactly one value"
    this.constValue = opts.constValue ?? opts.const ?? null;
    this.defaultValue = opts.defaultValue ?? opts.default ?? null;
    this.type = opts.type ?? null;
    this.choices = opts.choices ?? null;
    this.required = opts.required ?? false;
    this.help = opts.help ?? null;
    this.metavar = opts.metavar ?? null;
  }

  // CPython: Action.__call__ raises NotImplementedError('.__call__() not defined').
  call(parser, namespace, values, optionString) {
    throw new Error('.call() not defined');
  }
}

export class StoreAction extends Action {
  constructor(...args) {
    super(...args);
    // CPython _StoreAction.__init__ rejects these two configurations outright.
    if (this.nargs === 0) {
      throw new PyValueError(
        'nargs for store actions must be != 0; if you have nothing to store, '
        + 'actions such as store true or store const may be more appropriate',
      );
    }
    if (this.constValue !== null && this.nargs !== OPTIONAL) {
      throw new PyValueError(`nargs must be '${OPTIONAL}' to supply const`);
    }
  }

  // CPython: setattr(namespace, self.dest, values)
  call(parser, namespace, values, optionString) {
    namespace[this.dest] = values;
  }
}

export class HelpAction extends Action {
  constructor(...args) {
    super(...args);
    // CPython _HelpAction hard-codes nargs=0 and default=SUPPRESS, and the
    // parser registers it with this exact help string.
    this.nargs = 0;
    this.constValue = null;
    this.defaultValue = SUPPRESS; // so `help` never appears in the namespace
    this.dest = this.dest ?? 'help';
    this.help = this.help ?? 'show this help message and exit';
  }

  // CPython: parser.print_help(); parser.exit()  -> help on stdout, status 0.
  call(parser, namespace, values, optionString) {
    parser.printHelp();
    parser.exitWith(0);
  }
}

// argparse exception types — mirrors CPython 3.12 `argparse._get_action_name`,
// `argparse.ArgumentError` and `argparse.ArgumentTypeError`.

import { SUPPRESS } from './actions.mjs';

/**
 * CPython `_get_action_name(argument)`: the label used in
 * `argument NAME: <message>` errors.
 *   optionals  -> all option strings joined with '/'  ('-h/--help')
 *   otherwise  -> metavar, else dest, else null
 * SUPPRESS placeholders count as "unset", exactly as in CPython.
 */
export function getActionName(action) {
  if (action == null) {
    return null;
  }
  if (action.optionStrings != null && action.optionStrings.length > 0) {
    return action.optionStrings.join('/');
  }
  if (action.metavar != null && action.metavar !== SUPPRESS) {
    return action.metavar;
  }
  if (action.dest != null && action.dest !== SUPPRESS) {
    return action.dest;
  }
  return null;
}

/**
 * CPython `ArgumentError`. Its __str__ prefixes the message with the action
 * name when there is one, e.g. "argument --a: invalid int value: 'abc'".
 * Here that rendering is baked into `.message` since JS errors have no __str__.
 */
export class ArgumentError extends Error {
  constructor(action, message) {
    const argumentName = getActionName(action);
    super(argumentName == null ? message : `argument ${argumentName}: ${message}`);
    this.name = 'ArgumentError';
    this.argumentName = argumentName;
  }
}

/** CPython `ArgumentTypeError`: raised by a `type=` callable to reject a value. */
export class ArgumentTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentTypeError';
  }
}

// The `type=` callables argparse receives in test3.py (`int` and `str`).
//
// argparse reports conversion failures as
//   invalid ${type.name} value: ${reprStr(value)}
// which mirrors CPython's `getattr(action.type, '__name__', repr(action.type))`,
// so these MUST be declared as named functions called `int` and `str`.

import { pyIntFromString } from '../py/int.mjs';

/**
 * Python builtin `int(str)`: full CPython parse (Unicode Nd digits, PEP 515
 * underscores, whitespace stripping, sys.int_max_str_digits guard) -> BigInt.
 * Throws PyValueError on bad input, which argparse turns into
 * "argument --a: invalid int value: '...'".
 *
 * Declared with a single parameter on purpose: extra arguments from callers
 * (e.g. an Array#map index) must never reach pyIntFromString's digit limit.
 */
export function int(value) {
  return pyIntFromString(value);
}

/** Python builtin `str(s)` for a value that is already a str: identity. */
export function str(value) {
  return value;
}

