import { ArgumentError, ArgumentTypeError, getActionName } from './lib/argparse/errors.mjs';
import { int, str } from './lib/argparse/types.mjs';
import { Action, StoreAction, HelpAction, SUPPRESS } from './lib/argparse/actions.mjs';

const results = [];
const eq = (label, got, want) => results.push(`${got === want ? 'PASS' : 'FAIL'} ${label}: ${JSON.stringify(got)}${got === want ? '' : ' != ' + JSON.stringify(want)}`);

// type name fidelity (Python type.__name__)
eq('int.name', int.name, 'int');
eq('str.name', str.name, 'str');
eq('int("5")', int('5'), 5n);
eq('str("x")', str('x'), 'x');
eq('int via map ignores index', ['7'].map(int)[0], 7n);

// getActionName
const optA = new StoreAction({ optionStrings: ['--a'], dest: 'a', type: int, required: true });
const help = new HelpAction({ optionStrings: ['-h', '--help'], dest: 'help' });
eq('name optional', getActionName(optA), '--a');
eq('name help', getActionName(help), '-h/--help');
eq('name positional metavar', getActionName(new StoreAction({ optionStrings: [], dest: 'x', metavar: 'M' })), 'M');
eq('name positional dest', getActionName(new StoreAction({ optionStrings: [], dest: 'x' })), 'x');
eq('name SUPPRESS metavar falls through', getActionName(new StoreAction({ optionStrings: [], dest: 'x', metavar: SUPPRESS })), 'x');
eq('name all SUPPRESS', getActionName(new StoreAction({ optionStrings: [], dest: SUPPRESS, metavar: SUPPRESS })), null);
eq('name null', getActionName(null), null);

// ArgumentError messages verified against the reference binary
eq('err invalid int', new ArgumentError(optA, "invalid int value: 'abc'").message, "argument --a: invalid int value: 'abc'");
eq('err expected one', new ArgumentError(new StoreAction({ optionStrings: ['--b'], dest: 'b' }), 'expected one argument').message, 'argument --b: expected one argument');
eq('err ignored explicit', new ArgumentError(help, "ignored explicit argument 'x'").message, "argument -h/--help: ignored explicit argument 'x'");
eq('err no action', new ArgumentError(null, 'bare').message, 'bare');
eq('err argumentName', new ArgumentError(optA, 'm').argumentName, '--a');
eq('err is Error', new ArgumentError(optA, 'm') instanceof Error, true);
eq('err name', new ArgumentError(optA, 'm').name, 'ArgumentError');
eq('typeerr', new ArgumentTypeError('nope').message, 'nope');
eq('typeerr is Error', new ArgumentTypeError('n') instanceof Error, true);

// Action fields / defaults
const bare = new Action({});
eq('default optionStrings', JSON.stringify(bare.optionStrings), '[]');
eq('default nargs', bare.nargs, null);
eq('default required', bare.required, false);
eq('default constValue', bare.constValue, null);
eq('default defaultValue', bare.defaultValue, null);
eq('default type', bare.type, null);
eq('default choices', bare.choices, null);
eq('default help', bare.help, null);
eq('default metavar', bare.metavar, null);
eq('base call throws', (() => { try { bare.call(null, {}, 1, '--x'); return 'no-throw'; } catch (e) { return e.message; } })(), '.call() not defined');

// python-keyword aliases + positional-prefix construction
const alias = new Action({ option_strings: ['--z'], dest: 'z', const: 3, default: 9 });
eq('alias option_strings', alias.optionStrings.join(','), '--z');
eq('alias const', alias.constValue, 3);
eq('alias default', alias.defaultValue, 9);
const pos = new StoreAction(['--p'], 'p', { type: str, required: true });
eq('positional-style optionStrings', pos.optionStrings.join(','), '--p');
eq('positional-style dest', pos.dest, 'p');
eq('positional-style required', pos.required, true);
eq('string optionStrings', new Action('--s').optionStrings.join(','), '--s');
eq('falsy default kept', new Action({ default: false }).defaultValue, false);

// StoreAction behaviour + CPython validation
const ns = {};
optA.call(null, ns, 5n, '--a');
eq('store assigns', ns.a, 5n);
eq('store nargs 0 rejected', (() => { try { new StoreAction({ optionStrings: ['--q'], dest: 'q', nargs: 0 }); return 'no-throw'; } catch (e) { return e.constructor.name; } })(), 'PyValueError');
eq('store const needs ?', (() => { try { new StoreAction({ optionStrings: ['--q'], dest: 'q', constValue: 1 }); return 'no-throw'; } catch (e) { return e.constructor.name; } })(), 'PyValueError');
eq('store const with ? ok', new StoreAction({ optionStrings: ['--q'], dest: 'q', nargs: '?', constValue: 1 }).constValue, 1);

// HelpAction
eq('SUPPRESS value', SUPPRESS, '==SUPPRESS==');
eq('help nargs', help.nargs, 0);
eq('help default is SUPPRESS', help.defaultValue, SUPPRESS);
eq('help text', help.help, 'show this help message and exit');
eq('help dest', help.dest, 'help');
eq('help dest default', new HelpAction({ optionStrings: ['-h', '--help'] }).dest, 'help');
let trace = [];
const fakeParser = { printHelp() { trace.push('printHelp'); }, exitWith(s) { trace.push('exit:' + s); } };
help.call(fakeParser, {}, null, '-h');
eq('help call order', trace.join('|'), 'printHelp|exit:0');
eq('help instanceof Action', help instanceof Action, true);
eq('store instanceof Action', optA instanceof Action, true);

console.log(results.join('\n'));
console.log(results.some((r) => r.startsWith('FAIL')) ? 'SOME FAILED' : 'ALL PASS (' + results.length + ')');
EOF
node /tmp/argtest/t.mjs

